mapper.select:
SELECT * FROM pur_yt_apply_purchase
WHERE product_id = #{productId}
AND is_deleted = 0

SELECT * FROM pur_yt_apply_purchase
WHERE supplier_id = #{supplierId}
AND is_deleted = 0

