WHERE customer_id = #{customerId}
AND is_deleted = 0

update.foreach:
UPDATE pur_yt_apply_purchase
product_id = #{item.productId}, product_specification_id = #{item.productSpecificationId}, supplier_id = #{item.supplierId}, sales_employee_id = #{item.salesEmployeeId}, customer_id = #{item.customerId}, number = #{item.number}, category_label_id = #{item.categoryLabelId}, order_sub_id = #{item.orderSubId}, update_user = #{item.updateUser}, update_time = #{item.updateTime}, tenant_id = #{item.tenantId}, is_deleted = #{item.isDeleted}
WHERE id = #{item.id}

mapper.select:
SELECT pap.*, (select nick_name from sys_user as su where su.user_id=pap.sales_employee_id) as salesEmployeeName, (select name from sal_yt_customer as syc where syc.id = pap.customer_id) as customerName, (select code from pro_yt_product where id = pap.product_id) as productCode, sos.delivery_time,sos.order_time,sos.sub_code as orderSubCode,a.code as orderCode,a.remark as orderNote FROM pur_yt_apply_purchase as pap LEFT JOIN sal_yt_order_sub sos ON pap.order_sub_id = sos.id left join sal_yt_order a on sos.order_id=a.id LEFT JOIN pro_yt_product pp ON pap.product_id = pp.id LEFT JOIN pro_yt_product_specification pps ON pap.product_specification_id = pps.id LEFT JOIN sal_yt_customer sc ON pap.customer_id = sc.id LEFT JOIN sys_user su ON pap.sales_employee_id = su.user_id LEFT JOIN pur_yt_purchase_item ppi ON pap.id = ppi.apply_purchase_id WHERE pap.is_deleted = 0 AND pap.supplier_id = #{supplierId} AND (a.is_inbound_delivery = #{isInboundDelivery}
or a.is_inbound_delivery is null
)and pap.number>0
AND sos.sub_code LIKE CONCAT('%', #{orderSubCode}, '%')
AND a.code LIKE CONCAT('%', #{orderCode}, '%')
AND pp.code LIKE CONCAT('%', #{productCode}, '%')
AND pps.name LIKE CONCAT('%', #{specificationName}, '%')
AND (select name from pur_yt_supplier where id = pap.supplier_id) LIKE CONCAT('%', #{supplierName}, '%')
AND sc.name LIKE CONCAT('%', #{customerName}, '%')
AND pap.sales_employee_id = #{salesEmployeeId}
AND pap.id IN
#{id}
AND ppi.purchase_id = #{purchaseId}
ORDER BY pap.create_time DESC

SELECT pap.*, pp.code AS product_code, sc.name AS customer_name, ppss.supplier_specification AS supplier_specification, ppss.supplier_price, ppss.min_number AS minNumber, (select is_inbound_delivery from sal_yt_order_sub where id = pap.order_sub_id) as is_inbound_delivery, (select sub_code from sal_yt_order_sub where id = pap.order_sub_id) as orderSubCode, (select b.code from sal_yt_order_sub a left join sal_yt_order b on a.order_id=b.id where a.id=pap.order_sub_id) as orderCode, (select value from pro_yt_product_label where id = category_label_id) as categoryLabelName, (select b.remark from sal_yt_order_sub a left join sal_yt_order b on a.order_id=b.id where a.id=pap.order_sub_id) as orderNote, (select hand_product_level from pro_yt_product_specification where id = pap.product_specification_id) as handProductLevel FROM pur_yt_apply_purchase pap LEFT JOIN pro_yt_product pp ON pap.product_id = pp.id LEFT JOIN sal_yt_customer sc ON pap.customer_id = sc.id LEFT JOIN pro_yt_product_specification_supplier ppss ON pap.product_specification_id = ppss.specification_id AND pap.supplier_id = ppss.supplier_id WHERE pap.id IN
#{id}
AND pap.is_deleted = 0

SELECT pap.order_sub_item_id AS orderSubItemId, COALESCE(SUM(pap.number), 0) AS totalNumber FROM pur_yt_apply_purchase pap WHERE pap.is_deleted = 0 AND pap.order_sub_item_id IN
#{orderSubItemId}
GROUP BY pap.order_sub_item_id
